const express = require('express');
const router = express.Router();
const { Client } = require('@opensearch-project/opensearch');
const osClient = new Client({ node: process.env.OPENSEARCH_URL });

router.get('/api/infra/logs/search', requireCustomerToken, async (req, res) => {
  const { query, severity } = req.query;

  const mustClauses = [{ match: { message: query || '*' } }];
  if (severity) mustClauses.push({ term: { log_level: severity } });

  const searchResult = await osClient.search({
    index: 'cloud-cluster-audit-logs-*',
    body: {
      query: {
        bool: {
          must: mustClauses,
          filter: [
            { term: { customer_id: req.user.customerId } }
          ]
        }
      }
    }
  });

  const hits = searchResult.body.hits.hits.map(h => h._source);
  return res.json({ count: hits.length, logs: hits });
});
